import hashlib
import json
from pathlib import Path

ROOT = Path(r'E:\Dissertation')
OUT = ROOT / 'research_visible_part_2179_20261114/assignment_audit'
catalog_path = ROOT / 'experiments/project_history.json'
catalog = json.loads(catalog_path.read_text(encoding='utf-8'))
cards = {c['id']: c for c in catalog['experiments']}
evidence = 'research_visible_part_2179_20261114/assignment_audit/independent_audit.json'
corrections = []

def card(cid, field, new):
    corrections.append(dict(card_id=cid, field=field, old=cards[cid][field], new=new,
                            evidence=evidence,
                            reason='Уточнение физической интерпретации 2179: совпадение прямоугольников не доказывает принадлежность видимых пикселей. Числа исходного протокола и научный статус сохраняются.'))

cid = 'association_weights_2179_copy_20261112'
card(cid, 'obtained', cards[cid]['obtained'] + ' Эти числа правильных и неправильных назначений относятся к исходному правилу оценки по совпадению прямоугольников GT (эталонной разметки), а не к независимо установленной принадлежности видимых пикселей. На 1165 принадлежность всей области 110260 красной машине 2179 физически не подтверждена; назначение этой области 2445 нельзя по одному перекрытию GT объявлять ошибкой внешности. Дополнительный источник: ' + evidence + '. Численные результаты не пересчитаны.')
card(cid, 'interpretation', 'В этой фиксированной пробе ни один вариант весов не передал целевую рамку номеру 2179. Геометрическая стоимость и стоимость внешности обе предпочитают 2445 перед 2179 в рассматриваемом столбце; любая их выпуклая смесь сохраняет этот локальный порядок. Это не доказательство невозможности другого общего назначения или всех методов внешности. Источник: research_assignment_weights_2179_20261112/pairwise_dominance.json. На 1165 область 110260 включает ближнюю тёмную машину и видимую часть дальней красной; совпадение с GT 00122657 не доказывает, что вычисленный признак должен принадлежать красной машине. Поэтому сохранённое предпочтение 2445 пока не является доказанной физической ошибкой различения. Источник: ' + evidence + '.')
card(cid, 'decision', 'Сохранить выполненный откат всех пробованных параметров копии и исходные рабочие настройки. Не продвигать варианты с ухудшением либо неизвестными новыми назначениями. Не расширять подбор на этом случае. Сначала проверить физическое содержимое целевой области и независимо сопоставить видимые части двух машин; не считать передачу всей области номеру 2179 заранее правильной целью.')
card(cid, 'cannot_claim', cards[cid]['cannot_claim'] + ' На 1165 максимальное совпадение прямоугольника 110260 с GT 00122657 не устанавливает физическую принадлежность преобладающего содержимого; здесь нельзя объявлять 2445 чужим только по этому правилу. Полная перестановка идентификаторов GT также не доказана.')

cid = 'history_representation_2179_20261113'
card(cid, 'obtained', 'Шесть замен исторических образцов не дали номеру 2179 назначение целевой рамки на 1160/1165; всего 54 матрицы, 18 известных правильных назначений по прежнему протоколу оценки остаются 18. Источник: research_memory_2179_20261113/summary.json. Исходная/сглаженная рамка, ранний образец, набор прошлых образцов и заморозка 2445 проверены при прежних весах 0,25/1. Отрицательный контроль меняет целевое назначение, но добавляет ошибку 2445 на 1159 по исходному правилу оценки. Два технических отказа сохранены; восстановление размера пакета MASA даёт точное совпадение повторных признаков. Эти результаты описывают сохранённые матрицы и оценку по прямоугольникам; физическая правильность передачи области 110260 красной машине отдельно не установлена. Дополнительный источник: ' + evidence + '.')
card(cid, 'interpretation', 'Последующие обновления усиливают предпочтение 2445, но заморозка образца на 1159 сохраняет это предпочтение: обновление после 1159 не является необходимым условием измеренного порядка стоимостей на этих состояниях. Замена только сглаженной рамки исходной также не меняет требуемого назначения. Источники: research_memory_2179_20261113/audit.json; trace_v2.json. Отсюда нельзя вывести, что память уже содержит физически чужую машину: область 110260 на 1165 включает ближнюю тёмную машину, тогда как метка прежнего разбора получена по прямоугольнику дальней красной. Нужна отдельная проверка видимых частей. Источник: ' + evidence + '.')
card(cid, 'decision', 'Не продвигать проверенные варианты памяти: зарегистрированная цель передачи целевой рамки номеру 2179 не достигнута. Сохранить отрицательный вычислительный результат, но сначала проверить саму физическую трактовку целевой рамки. Следующий опыт разделяет доступную часть красной машины, тёмную машину и остальную сцену; он не должен заранее считать предпочтение 2445 ошибочным. Полный трекер остаётся запрещён.')
card(cid, 'cannot_claim', cards[cid]['cannot_claim'] + ' На 1165 не доказано, что предпочтение 2445 является физически неверным: видимое содержимое смешано, а прежняя принадлежность целевой рамки определена по GT-прямоугольнику. Не доказаны ошибочное запоминание чужого объекта, полная перестановка GT-идентификаторов и правильность принудительной передачи 110260 номеру 2179.')

for cid in ['identity_repair_holdout_selection_20261112', 'identity_repair_holdout_bank_20261112', 'identity_repair_holdout_correspondence_20261112', 'identity_repair_holdout_recovery_20261112']:
    old = cards[cid]['cannot_claim']
    new = old.replace('Положительный разбор2179не означает, что найден точный первый ошибочный семантический кадр или восстановлен старый номер.', 'Разбор 2179 объяснил воспроизведённое назначение сохранённой матрицы, но не доказал физическую ошибочность выбора 2445: на 1165 область 110260 содержит обе машины, а прежняя связь с 2179 получена по совпадению прямоугольников. Первый физически ошибочный кадр, полная перестановка GT-идентификаторов и восстановление старого номера не установлены.')
    card(cid, 'cannot_claim', new + ' Числа ранее зарегистрированной проверки сохранены без пересчёта; новые ограничения касаются физической трактовки случая 2179. Источник: ' + evidence + '.')

cid = 'identity_repair_holdout_recovery_20261112'
card(cid, 'obtained', cards[cid]['obtained'] + ' Оценки 1/2→1/2 и 0/1→0/1 сохранены как результат исходного протокола по прямоугольникам GT; физическая принадлежность спорной области 2179 на 1165 требует отдельной проверки и не подтверждается этими дробями.')

report_path = ROOT / 'research_memory_2179_20261113/РЕЗУЛЬТАТ.md'
paras = report_path.read_text(encoding='utf-8').split('\n\n')
def report(prefix, new):
    found = [p for p in paras if p.startswith(prefix)]
    assert len(found) == 1, prefix
    corrections.append(dict(card_id='report:research_memory_2179_20261113/РЕЗУЛЬТАТ.md', field='paragraph', old=found[0], new=new, evidence=evidence,
                            reason='Сохранить исходный текст в истории и добавить датированную поправку: измеренное предпочтение не равно доказанной физической ошибке.'))

report('Ни одно из шести правил памяти', 'Ни одно из шести правил памяти не назначило целевую рамку номеру 2179 на 1160 или 1165. Не помогли исходная рамка детектора вместо сглаженной, самый ранний из сохранённых образцов, минимум расстояния по набору прошлых образцов и заморозка образца 2445 на 1158/1159. При весе 0,25 сохраняются 18 известных правильных назначений и 1 неправильное; при весе 1 остаются 18 правильных и 3 неправильных, как у прежней внешности с этим весом. Эти числа относятся к исходному протоколу оценки по прямоугольникам. Новые ошибки большого веса не вызваны заменой памяти: они уже есть в согласованном контроле. Источник: summary.json/variants. Физическая правильность передачи спорной области номеру 2179 отдельно не установлена.')
report('На точно размеченном1159', 'На размеченном кадре 1159 номер 2179 связан с GT 00122657, а назначение 2445 имеет наибольшее совпадение с GT 00122746. Однако рамка 2445 геометрически покрывает большую часть прямоугольника 2179. Покрытие исходной и сглаженной рамкой измерено отдельно в summary.json/coverage_target_in_competitor_box1159. Это пересечение прямоугольников разметки, не доля видимых пикселей. На 1165 прямоугольник GT 00122657 совпадает с широкой областью, содержащей видимые части двух машин; такая геометрическая метка не доказывает, что признак области должен описывать дальнюю красную машину. Источник дополнительной сверки: ' + evidence + '.')
report('На1165стоимость внешности', 'На 1165 стоимость внешности для 2179→110260 равна 0,359247, а для 2445→110260 — 0,012743. Заморозка 2445 на 1159 увеличивает вторую стоимость до 0,108202, но предпочтение 2445 и итоговое назначение сохраняются. Следовательно, последующие обновления усилили это предпочтение, но не являются необходимым условием измеренного порядка стоимостей на сохранённом состоянии. Замена только сглаженной рамки исходной также не меняет назначения. Здесь не доказана физическая ошибочность выбора 2445: видимое содержимое целевой области включает ближнюю тёмную машину. Источники: audit.json/summary, policy freeze2445_1159 и latest_raw; ' + evidence + '.')
report('Набор прошлых образцов', 'Набор прошлых образцов с выбором минимального расстояния сохраняет сильное сходство целевой области с одним из образцов 2445. Добавление истории само по себе не меняет это предпочтение. Называть выбранный образец физически неподходящим до проверки содержимого целевой области нельзя. Deep SORT использует набор прошлых признаков и минимальное косинусное расстояние; статья обосновывает такой контроль, но не гарантирует устойчивость к ошибочным историческим назначениям. Источники: https://arxiv.org/html/1703.07402, раздел 2.2; наш результат audit.json, policy gallery_raw.')
report('Перестановка последних образцов', 'Перестановка последних образцов двух номеров при весе 1 передаёт целевую рамку 2179 на 1160 и 1165, но добавляет ошибочное назначение 2445 на 1159 по исходному правилу оценки. Это отрицательный контроль: он подтверждает влияние признаков на результат, но не является допустимым исправлением. Точной разметки 1160 нет; физическая правильность передачи смешанной области 110260 номеру 2179 на 1165 также не доказана. Изменение назначения не объявляется восстановлением личности. Источник: summary.json, policy swap_latest_negative; ' + evidence + '.')
report('Шесть проверенных замен памяти не принимать.', 'Шесть проверенных замен памяти не принимать. Рабочие настройки, веса моделей и прежние результаты сохранены; ядро и полный трекер не запускались. Измеренное предпочтение 2445 не объясняется только возрастом последнего образца или сглаживанием рамки: оно сохраняется до последующих обновлений памяти. Но называть это предпочтение физически неверным преждевременно, поскольку целевая область содержит две машины, а её связь с красной машиной установлена по прямоугольнику GT. Единственная физическая причина смешения признаков, ошибочное запоминание чужой машины и первый кадр переноса номера пока не доказаны.')
report('Следующая содержательная правка', 'Следующая диагностическая проверка должна разделить физически видимые части красной машины, тёмной машины и остальную сцену с согласованным контролем полного прямоугольника. Принудительное предпочтение 2179 не принимается заранее за правильный исход. Повторять сетку весов или просто увеличивать память не обосновано. Это направление следующей регистрации, не выполненный здесь опыт и не доказанное решение.')
report('По числу подтверждённых правильных назначений:', 'По числу правильных назначений по исходному протоколу: 18→18, изменение 0 процентов к исходному варианту для шести правил памяти. Назначений целевой рамки номеру 2179 в двух состояниях 0→0; относительный процент при нулевой базе не определяется. Эти числа не доказывают физическую правильность принадлежности смешанной области на 1165. Доля измеренного потолка неизвестна. Это локальная проверка сопоставления, не HOTA и не качество полного трекера.')

payload = dict(scope='Suggested corrections only; shared records not edited. Preserve old text in revisions; do not alter original numeric artifacts or scientific statuses.',
               source_sha256={str(p.relative_to(ROOT)): hashlib.sha256(p.read_bytes()).hexdigest() for p in [catalog_path, report_path]},
               corrections=corrections)
(OUT / 'suggested_corrections.json').write_text(json.dumps(payload, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'corrections':len(corrections), 'path':str(OUT / 'suggested_corrections.json')}, ensure_ascii=False))
